WITH RecentUserPostStats AS (
    SELECT
        u.Id AS UserId,
        u.DisplayName,
        COUNT(DISTINCT p.Id) FILTER (WHERE p.PostTypeId = 1 AND p.CreationDate > NOW() - INTERVAL '1 year') AS RecentQuestions,
        COUNT(DISTINCT p.Id) FILTER (WHERE p.PostTypeId = 2 AND p.CreationDate > NOW() - INTERVAL '1 year') AS RecentAnswers,
        AVG(COALESCE(p.Score,0)) FILTER (WHERE p.CreationDate > NOW() - INTERVAL '1 year') AS AvgScore,
        MAX(p.CreationDate) AS LastPostDate
    FROM Users u
    LEFT JOIN Posts p ON p.OwnerUserId = u.Id
    GROUP BY u.Id, u.DisplayName
),
